// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        c = new C(0, 0, 0);
        owner = address(0x1);
        vm.prank(owner);
        c = new C(100, "", "");
    }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 burnAmount) public {
        // Ensure caller is not zero address (avoid transfer to zero in setup)
        vm.assume(caller != address(0));

        // Mint initialBalance to caller (only owner can mint)
        vm.prank(owner);
        c.mintToken(caller, initialBalance);

        // Bound burnAmount to be <= initialBalance (otherwise burn will revert)
        vm.assume(burnAmount <= initialBalance);

        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(caller);

        // Perform burn as caller
        vm.prank(caller);
        c.burn(burnAmount);

        // General rule: balance after burn should be balanceBefore - burnAmount
        uint256 balanceAfter = c.balanceOf(caller);
        assertTrue(balanceAfter == balanceBefore - burnAmount, "Balance should decrease by burn amount");
    }
}

