pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 burnValue) public {
        vm.assume(caller != address(0));
        vm.assume(initialBalance >= 1 && initialBalance <= 1e30);
        vm.assume(burnValue <= initialBalance);
        vm.assume(burnValue >= 1);

        // Set up initial balance for caller
        address owner = 0x0000000000000000000000000000000000000001;
        vm.prank(owner);
        c.mintToken(caller, initialBalance);

        uint256 balanceBefore = c.balanceOf(caller);
        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnValue));

        if (success) {
            uint256 balanceAfter = c.balanceOf(caller);
            // In the correct version, balanceAfter = balanceBefore - burnValue
            // In the buggy version, balanceAfter = burnValue
            assertTrue(balanceAfter <= balanceBefore, "Balance should not increase after burn");
        }
    }
}

