        vm.assume(initialBalance > 0);
        vm.assume(caller != address(0));
        // Fund the caller by minting
        vm.prank(c.address);
        c.mintToken(caller, initialBalance);
        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(caller);
        // Execute burn as the caller
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnValue));
        if (!ok) {
            assertTrue(true); // revert is acceptable, rule vacuously holds
            return;
        }
        uint256 balanceAfter = c.balanceOf(caller);
        assertTrue(balanceAfter <= balanceBefore);
    }
}

