pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialBalance, uint256 burnAmount) public {
        vm.assume(initialBalance > 0 && burnAmount > 0 && burnAmount <= initialBalance);
        vm.assume(initialBalance <= type(uint256).max / 2);
        c.mintToken(address(this), initialBalance);
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();
        (bool ok,) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        assertTrue(ok, "burn reverted");
        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 balanceDecrease = balanceBefore - balanceAfter;
        uint256 supplyDecrease = totalSupplyBefore - totalSupplyAfter;
        assertTrue(balanceDecrease == supplyDecrease, "balance decrease != supply decrease");
    }
}

