pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    function testFuzz_property(address burner, uint256 initialBalance, uint256 burnAmount) public {
        // Bound parameters to reasonable values
        initialBalance = bound(initialBalance, 0, 1e30);
        burnAmount = bound(burnAmount, 0, initialBalance);

        // Precondition: need tokens to burn, so mint to burner
        vm.assume(burner != address(0));
        vm.prank(c.owner());
        c.mintToken(burner, initialBalance);

        // Record pre-state
        uint256 preBalance = c.balanceOf(burner);
        uint256 preSupply = c.totalSupply();

        // Burn as the burner
        vm.prank(burner);
        try c.burn(burnAmount) {
            // Post-state
            uint256 postBalance = c.balanceOf(burner);
            uint256 postSupply = c.totalSupply();
            // General rule: balance decreases by burnAmount, totalSupply decreases by burnAmount
            assertTrue(
                preBalance - postBalance == burnAmount &&
                preSupply - postSupply == burnAmount,
                "burn should decrease balance and totalSupply by burnAmount"
            );
        } catch {
            // If burn reverts, then burnAmount must be > preBalance (should not happen due to bound)
            assertTrue(burnAmount > preBalance, "unexpected revert");
        }
    }
}

