pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0 && burnAmount <= 100000);
        address burner = address(0x1234);
        vm.deal(burner, 1 ether);
        vm.prank(burner);
        c.mintToken(burner, 1000000);
        uint256 balanceBefore = c.balanceOf(burner);
        uint256 supplyBefore = c.totalSupply();
        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        if (!success) {
            assertTrue(balanceBefore < burnAmount || balanceBefore == 0);
        } else {
            uint256 balanceAfter = c.balanceOf(burner);
            uint256 supplyAfter = c.totalSupply();
            assertTrue(balanceAfter + supplyAfter == balanceBefore + supplyBefore - burnAmount);
        }
    }
}

