pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address target, bool freeze, uint256 burnAmount) public {
        vm.assume(burnAmount <= 0); // burn must succeed, but amount is 0 because totalSupply is 0
        vm.assume(target != address(0)); // avoid zero address issues
        vm.assume(target != address(this)); // avoid owner interference

        // Freeze the target account
        vm.prank(c.owner());
        c.freezeAccount(target, freeze);

        // Record the frozen state before burn
        bool frozenBefore = c.frozenAccount(target);

        // Perform burn
        vm.prank(c.owner());
        c.burn(burnAmount);

        // After burn, frozenAccount should remain unchanged for target
        bool frozenAfter = c.frozenAccount(target);

        // General rule: freezeAccount didn't change the mapping, so frozenAccount stays as initialized (false)
        // But in the reference, it does change, so this assertion will fail for the buggy version
        assertTrue(frozenBefore == frozenAfter, "frozen state should not change after burn");
    }
}

